typedef unsigned int color32;

struct FEMenu;
struct FEMenuSystem {
    char padding[0x74];
    FEMenu **menus;
};

struct FEMenu {
    char padding0[0x34];
    float scale_high;
    char padding1[0x4];
    int flags;
    char padding2[0x14];
    FEMenu *back;
    int back_num;
    char padding3[0x18];
    const void *vtable;
};

struct CameraMenuClass {
    FEMenu base;
    FEMenuSystem *sys;
    FEMenu *menu_item[3];
    bool multiplayer;
};

extern "C" void FEMenuCtor(FEMenu *self) __asm__("__6FEMenu");
extern "C" void FEMenuCons(
    FEMenu *self, FEMenuSystem *system, int x, int y,
    color32 color, color32 color_high, color32 color_high_alt,
    float scale, float scale_high, int max_visible, int flags)
    __asm__("cons__6FEMenuP12FEMenuSystemiiG7color32N24ffii");
extern "C" void SetHelpText(FEMenu *self, int flags)
    __asm__("SetHelpText__6FEMenui");
extern const char camera_menu_vtable[];

__asm__(".equ __6FEMenu, 0x00156280");
__asm__(".equ cons__6FEMenuP12FEMenuSystemiiG7color32N24ffii, 0x00156330");
__asm__(".equ SetHelpText__6FEMenui, 0x00156E20");
__asm__(".equ camera_menu_vtable, 0x004C7F30");

extern "C" CameraMenuClass *CameraMenuCtor(
    CameraMenuClass *self, FEMenuSystem *system, int x, int y,
    color32 color, color32 color_high, color32 color_high_alt)
    __asm__("__15CameraMenuClassP12FEMenuSystemiiG7color32N24");

CameraMenuClass *CameraMenuCtor(
    CameraMenuClass *self, FEMenuSystem *system, int x, int y,
    color32 color, color32 color_high, color32 color_high_alt)
{
    FEMenuCtor(&self->base);
    self->base.vtable = camera_menu_vtable;
    FEMenuCons(&self->base, system, x, y, color, color_high, color_high_alt,
               1.0f, 1.2f, 8, 0);

    self->sys = system;

    for (int i = 0; i < 3; i++)
        self->menu_item[i] = 0;

    self->base.back = self->sys->menus[7];
    self->base.back_num = 1;
    self->base.scale_high = 1.0f;
    SetHelpText(&self->base, 0x73);
    self->base.flags |= 2;
    return self;
}
